-- Mission story, proof and things to know for every launch company
UPDATE public.stocks SET mission_story = 'Develops medicines and vaccines, led by Keytruda, an immunotherapy that helps the immune system find and attack cancer.', proof = 'Keytruda was the world''s best-selling medicine in 2024, with about $29.5 billion in sales.', proof_source_url = 'https://biospace.com/business/10-best-selling-drugs-of-2024-rake-in-billions-amid-exclusivity-threats',
  things_to_know = ARRAY['Keytruda brings in nearly half of Merck''s sales, and its main U.S. patents start expiring in 2028.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'MRK';
UPDATE public.stocks SET mission_story = 'Develops medicines for cancer, blood disorders, immune diseases and heart disease, including the cancer immunotherapy Opdivo.', proof = 'Opdivo is approved for many cancers, including lung, skin, kidney and bladder cancer.', proof_source_url = 'https://seer.cancer.gov/seertools/seerrx/rx/65ef512cc69eb00584e5b6b5',
  things_to_know = ARRAY['Its two biggest medicines, Eliquis and Opdivo, lose U.S. patent protection around 2028 to 2029.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'BMY';
UPDATE public.stocks SET mission_story = 'Develops medicines for immune diseases, cancer and brain conditions, plus Botox through its Allergan business.', proof = 'Its cancer drugs include Imbruvica and Venclexta, used to treat blood cancers such as leukemia.', proof_source_url = 'https://www.cancer.gov/news-events/cancer-currents-blog/2019/venetoclax-obinutuzumab-fda-approval-cll-sll',
  things_to_know = ARRAY['Its former top seller, Humira, now faces lower-cost biosimilar competition.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ABBV';
UPDATE public.stocks SET mission_story = 'A biotechnology pioneer making medicines for cancer, bone loss, heart disease and inflammation.', proof = 'Its cancer medicines include Kyprolis for multiple myeloma and Blincyto for leukemia.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/318154/000031815426000010/amgn-20251231.htm',
  things_to_know = ARRAY['Took on about $28 billion of debt to buy Horizon Therapeutics for $27.8 billion in 2023.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'AMGN';
UPDATE public.stocks SET mission_story = 'Discovers antibody medicines for eye disease, allergies, asthma and cancer, using its own genetic research tools.', proof = 'Its Libtayo is an approved immunotherapy for certain skin and lung cancers.', proof_source_url = 'https://www.nasdaq.com/articles/regn-gets-ec-nod-libtayo-label-expansion-fda-clears-monthly-eylea-hd',
  things_to_know = ARRAY['Its eye drug Eylea, long its biggest product, is losing sales to newer competition.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'REGN';
UPDATE public.stocks SET mission_story = 'Develops medicines for HIV, liver disease and cancer, including cell therapies that reprogram immune cells to fight cancer.', proof = 'Its Kite unit makes the CAR T-cell therapies Yescarta and Tecartus for blood cancers.', proof_source_url = 'https://investors.gilead.com/news/news-details/2025/Gilead-Sciences-Announces-Fourth-Quarter-and-Full-Year-2024-Financial-Results/default.aspx',
  things_to_know = ARRAY['About two-thirds of its sales come from HIV medicines rather than cancer.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'GILD';
UPDATE public.stocks SET mission_story = 'Develops mRNA medicines and vaccines, including COVID-19 and RSV vaccines and personalized cancer vaccines made for each patient''s tumor.', proof = 'In August 2026, its personalized melanoma vaccine, given with Merck''s Keytruda, kept patients cancer-free longer than Keytruda alone in a late-stage trial.', proof_source_url = 'https://www.merck.com/news/merck-and-moderna-announce-phase-3-interpath-001-trial-of-intismeran-autogene-plus-keytruda-met-endpoints-of-recurrence-free-survival-rfs-and-distant-metastasis-free-survival-dmfs-in-patient/',
  things_to_know = ARRAY['Its shares jumped 177% in one day on those trial results, but the vaccine isn''t approved yet, and it lost about $2.8 billion in 2025.']::text[], in_feed = true,
  caution_headline = 'Up about 644% in the year to Oct 26, 2026', caution_reason = 'It jumped about 177% in one day in August 2026 after Moderna and Merck said their personalized melanoma vaccine met its main goal in a late-stage trial. The vaccine is not approved yet.', caution_source_url = 'https://www.tikr.com/blog/moderna-mrna-stock-skyrockets-melanoma-vaccine-trial-results', caution_checked_on = '2026-10-27'
  WHERE ticker = 'MRNA';
UPDATE public.stocks SET mission_story = 'A German biotech developing cancer immunotherapies and vaccines, best known for co-developing the Pfizer-BioNTech COVID-19 vaccine.', proof = 'It co-developed the first COVID-19 vaccine authorized in the U.S., in December 2020.', proof_source_url = 'https://www.scientificamerican.com/article/pfizer-biontech-covid-vaccine-is-first-to-win-u-s-authorization',
  things_to_know = ARRAY['Its cancer medicines are still in clinical trials, and it lost about €1.1 billion in 2025.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'BNTX';
UPDATE public.stocks SET mission_story = 'Develops medicines that treat the root causes of serious diseases like cystic fibrosis and sickle cell disease.', proof = 'Its Casgevy, approved in December 2023, was the first approved CRISPR gene-editing therapy.', proof_source_url = 'https://www.fool.com/investing/2023/12/15/after-this-landmark-win-is-crispr-a-buy',
  things_to_know = ARRAY['Most of its revenue still comes from cystic fibrosis medicines.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'VRTX';
UPDATE public.stocks SET mission_story = 'Develops therapies for neurological diseases such as multiple sclerosis, spinal muscular atrophy and Alzheimer''s disease.', proof = 'It co-developed Leqembi, which won full FDA approval in July 2023 as a treatment that slows early Alzheimer''s disease.', proof_source_url = 'https://www.biospace.com/fda-grants-traditional-approval-for-leqembi-lecanemab-irmb-for-the-treatment-of-alzheimer-s-disease',
  things_to_know = ARRAY['Its older multiple sclerosis drugs face falling sales from generic competition.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'BIIB';
UPDATE public.stocks SET mission_story = 'Makes tools used to research diseases, manufacture biologic medicines and diagnose patients, through brands like Cytiva, Beckman Coulter and Cepheid.', proof = 'Its Cepheid unit makes the Xpert MTB/RIF tuberculosis test, which the World Health Organization endorsed in 2010.', proof_source_url = 'https://www.who.int/news/item/08-12-2010-who-endorses-new-rapid-tuberculosis-test',
  things_to_know = ARRAY['Demand for its tools slowed after the COVID-19 testing boom ended.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'DHR';
UPDATE public.stocks SET mission_story = 'Develops blood tests that find cancer and help doctors choose treatments, without needing a tissue biopsy.', proof = 'Its Shield test became the first FDA-approved blood test for primary colorectal cancer screening, in July 2024.', proof_source_url = 'https://ascopost.com/news/july-2024/guardant-health-s-shield-blood-test-approved-by-the-fda-as-a-primary-screening-option-for-colorectal-cancer',
  things_to_know = ARRAY['Lost about $416 million in 2025; growth depends on doctors and insurers adopting its tests.']::text[], in_feed = true,
  caution_headline = 'Up about 140% in the year to Oct 26, 2026', caution_reason = 'In July 2026 UnitedHealth became the first large private insurer to cover its Shield colon cancer blood test, which an analyst called a watershed moment.', caution_source_url = 'https://www.medtechdive.com/news/guardants-shield-colon-cancer-blood-test-snags-unitedhealth-coverage/824365/', caution_checked_on = '2026-10-27'
  WHERE ticker = 'GH';
UPDATE public.stocks SET mission_story = 'Develops genetic blood tests that check whether cancer has returned, screen pregnancies and monitor transplanted organs.', proof = 'Its Signatera test is personalized to each patient''s tumor to detect cancer recurrence from a blood draw.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1604821/000110465926020881/ntra-20251231x10k.htm',
  things_to_know = ARRAY['Has reported a net loss every year since it was founded.']::text[], in_feed = true,
  caution_headline = 'Up about 110% in the year to Oct 26, 2026', caution_reason = 'Its revenue grew about 38% in the second quarter of 2026 as more doctors ordered its tests, led by its Signatera cancer-recurrence test.', caution_source_url = 'https://www.360dx.com/cancer/natera-preparing-prospective-study-readouts-accelerate-q2-revenue-climbs-38-percent', caution_checked_on = '2026-10-27'
  WHERE ticker = 'NTRA';
UPDATE public.stocks SET mission_story = 'Makes the DNA sequencing machines labs use to read genes, study cancer and diagnose genetic disease.', proof = 'In 2022 it launched sequencers that can read a whole human genome for about $200.', proof_source_url = 'https://www.medtechdive.com/news/illumina-ushers-in-200-genome-with-the-launch-of-new-sequencers/633133/',
  things_to_know = ARRAY['Spun off the cancer-test maker Grail in June 2024 after European regulators blocked the deal.']::text[], in_feed = true,
  caution_headline = 'Up about 171% in the year to Oct 26, 2026', caution_reason = 'It beat sales expectations and raised its 2026 forecast three quarters in a row as demand for gene sequencing in cancer care grew.', caution_source_url = 'https://www.tikr.com/blog/illumina-stock-is-up-82-in-six-months-the-streets-target-still-trails-it', caution_checked_on = '2026-10-27'
  WHERE ticker = 'ILMN';
UPDATE public.stocks SET mission_story = 'Develops medicines for blood cancers, other cancers and inflammatory skin conditions.', proof = 'Its drug Jakafi treats myelofibrosis and polycythemia vera, two rare blood cancers.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/879169/000110465925041229/tm2510810d2_ars.pdf',
  things_to_know = ARRAY['Jakafi, its main drug, loses U.S. patent protection in 2028.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'INCY';
UPDATE public.stocks SET mission_story = 'A focused cancer-drug company whose main medicine, Cabometyx, treats several advanced cancers.', proof = 'Its drug Cabometyx is approved for advanced kidney cancer, liver cancer and, since 2025, neuroendocrine tumors.', proof_source_url = 'https://www.businesswire.com/news/home/20260804452015/en/',
  things_to_know = ARRAY['About 90% of its revenue comes from a single drug, Cabometyx.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'EXEL';
UPDATE public.stocks SET mission_story = 'Pioneered medicines that switch off disease-causing genes, starting with rare inherited diseases and expanding into heart disease.', proof = 'Its Onpattro, approved in August 2018, was the first FDA-approved RNAi medicine.', proof_source_url = 'https://www.neurologylive.com/view/fda-approves-patisiran-infusion-for-polyneuropathy-in-hattr',
  things_to_know = ARRAY['Turned profitable for the first time in 2025, but its shares fell about 28% in one day in July 2026 when sales of its main medicine, Amvuttra, missed forecasts.']::text[], in_feed = true,
  caution_headline = 'Down about 51% in the year to Oct 26, 2026', caution_reason = 'It fell about 28% in one day in July 2026 when sales of its main medicine, Amvuttra, missed forecasts.', caution_source_url = 'https://www.fiercepharma.com/pharma/alnylam-turns-profitable-even-amvuttra-attr-revenue-disappoints-q4', caution_checked_on = '2026-10-27'
  WHERE ticker = 'ALNY';
UPDATE public.stocks SET mission_story = 'Develops medicines for rare genetic diseases that often have few or no other treatments.', proof = 'Its Voxzogo was the first approved medicine to increase growth in children with achondroplasia, the most common form of dwarfism.', proof_source_url = 'https://www.managedhealthcareexecutive.com/view/fda-approves-first-drug-for-a-form-of-dwarfism',
  things_to_know = ARRAY['Agreed in December 2025 to buy Amicus Therapeutics for about $4.8 billion, paid for partly with new debt.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'BMRN';
UPDATE public.stocks SET mission_story = 'Makes the kits and tests labs use to extract and analyze DNA, including tests for tuberculosis, infections and cancer markers.', proof = 'Its QuantiFERON-TB Gold Plus test is widely used to screen for latent tuberculosis infection.', proof_source_url = 'https://www.qiagen.com/products/diagnostics-and-clinical-research/tb-management/quantiferon-tb-gold-plus',
  things_to_know = ARRAY['Has been reviewing a possible sale since early 2026, and private equity firms have reportedly shown interest.', 'Based in the Netherlands, so its reported results are sensitive to currency swings.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'QGEN';
UPDATE public.stocks SET mission_story = 'Makes medical devices, diagnostic tests, nutrition products and medicines, including the FreeStyle Libre glucose monitor.', proof = 'More than 7 million people in over 60 countries use its FreeStyle Libre glucose monitors.', proof_source_url = 'https://www.abbott.com/en-us/corpnewsroom/careers/revolutionizing-diabetes-care-to-make-a-difference',
  things_to_know = ARRAY['Faces lawsuits claiming its formula for premature babies caused a serious bowel disease; it lost large jury verdicts and is appealing.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ABT';
UPDATE public.stocks SET mission_story = 'Makes continuous glucose monitors that let people with diabetes track their blood sugar in real time without finger pricks.', proof = 'In March 2024 its Stelo became the first glucose biosensor cleared by the FDA for sale without a prescription.', proof_source_url = 'https://www.medtechdive.com/news/dexcom-over-the-counter-cgm/709615/',
  things_to_know = ARRAY['Faces strong competition from Abbott''s FreeStyle Libre.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'DXCM';
UPDATE public.stocks SET mission_story = 'Makes the Omnipod, a small tubeless insulin pump worn on the body, for people with diabetes.', proof = 'Omnipod 5 works with continuous glucose monitors to adjust insulin delivery automatically.', proof_source_url = 'https://www.omnipod.com/about-omnipod/omnipod-CGM/',
  things_to_know = ARRAY['Recalled some Omnipod 5 pods in March 2026 over insulin leaks, and cut its U.S. sales growth forecast in August as competition grew.', 'Competes with other insulin pump makers, including Medtronic''s MiniMed and Tandem Diabetes Care.']::text[], in_feed = true,
  caution_headline = 'Down about 53% in the year to Oct 26, 2026', caution_reason = 'It forecast slower growth for 2026, then in March recalled some Omnipod 5 insulin pods because a tear in the tubing could let insulin leak.', caution_source_url = 'https://www.tikr.com/blog/insulet-podd-stock-drops-7-after-omnipod-5-recall', caution_checked_on = '2026-10-27'
  WHERE ticker = 'PODD';
UPDATE public.stocks SET mission_story = 'Makes the da Vinci robotic surgery system, which helps surgeons perform minimally invasive operations.', proof = 'Surgeons have performed more than 20 million procedures with Intuitive''s da Vinci and Ion systems.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1035267/000103526726000025/a2025_annualreportxv4.pdf',
  things_to_know = ARRAY['Faces its first major competitor in the U.S. since Medtronic''s Hugo surgical robot was cleared by the FDA in December 2025.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ISRG';
UPDATE public.stocks SET mission_story = 'Makes heart valves and devices that let doctors replace or repair heart valves without open-heart surgery.', proof = 'Its SAPIEN valve became the first transcatheter aortic valve approved in the U.S., in 2011.', proof_source_url = 'https://www.biospace.com/fda-approves-edwards-lifesciences-s-less-invasive-heart-valve',
  things_to_know = ARRAY['Sold its critical care business to BD for $4.2 billion in 2024 to focus on heart valves and other structural heart devices.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'EW';
UPDATE public.stocks SET mission_story = 'Makes devices for heart, vascular, digestive and urological conditions, including treatments for irregular heartbeat.', proof = 'Its Farapulse system, approved in the U.S. in January 2024, brought in over $1 billion in its first year treating atrial fibrillation.', proof_source_url = 'https://www.fiercebiotech.com/medtech/boston-scientific-clocks-over-1b-farapulse-revenue-afib-therapys-first-year',
  things_to_know = ARRAY['Its shares fell by about half from late 2025 as rivals slowed U.S. sales of its Farapulse heart device.', 'Agreed in January 2026 to buy Penumbra for about $14.5 billion.']::text[], in_feed = true,
  caution_headline = 'Down about 55% in the year to Oct 26, 2026', caution_reason = 'It fell about 17% in one day in February 2026 when sales of its heart-rhythm devices missed forecasts as rival devices from Johnson & Johnson and Medtronic took share.', caution_source_url = 'https://www.startribune.com/boston-scientific-stock/601576627', caution_checked_on = '2026-10-27'
  WHERE ticker = 'BSX';
UPDATE public.stocks SET mission_story = 'One of the largest medical device companies, making pacemakers, heart devices, spine implants and surgical tools.', proof = 'Its Micra is a leadless pacemaker about one-tenth the size of a traditional one, placed in the heart through a vein.', proof_source_url = 'https://www.fiercebiotech.com/medical-devices/medtronic-implants-world-s-tiniest-pacemaker-first-patients',
  things_to_know = ARRAY['Is separating its diabetes business, MiniMed, which began trading as its own company in March 2026.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'MDT';
UPDATE public.stocks SET mission_story = 'Makes orthopedic implants, surgical equipment and robotic systems for joint replacement.', proof = 'Its Mako robotic arm helps surgeons with total knee, partial knee and total hip replacements.', proof_source_url = 'https://www.orthoworld.com/the-state-of-joint-replacement-2026/',
  things_to_know = ARRAY['Sales of big equipment like Mako robots depend on hospitals'' capital budgets.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'SYK';
UPDATE public.stocks SET mission_story = 'Makes knee and hip replacement implants and related surgical technology.', proof = 'It is one of the largest makers of knee and hip replacement implants.', proof_source_url = 'https://www.orthoworld.com/the-state-of-joint-replacement-2026/',
  things_to_know = ARRAY['Has had more joint-implant recalls than its main rivals, according to a 2026 analysis of FDA records.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ZBH';
UPDATE public.stocks SET mission_story = 'Makes CPAP machines and masks that treat sleep apnea, plus cloud software that tracks patients'' therapy.', proof = 'Its AirSense machines send therapy data to its AirView cloud system, so care teams can check how patients are doing.', proof_source_url = 'https://www.resmed.com/en-us/healthcare-professional/products-and-support/monitoring-and-data-management/airview',
  things_to_know = ARRAY['Weight-loss drugs could reduce sleep apnea cases over time, a debated risk to its sales.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'RMD';
UPDATE public.stocks SET mission_story = 'Makes a small implant that treats sleep apnea by keeping the airway open during sleep, for people who can''t tolerate CPAP.', proof = 'Its therapy works by stimulating the nerve that moves the tongue, keeping the airway open during sleep.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1609550/000160955023000024/insp-20221231.htm',
  things_to_know = ARRAY['A rival implant, Nyxoah''s Genio, won FDA approval in August 2025, ending Inspire''s run as the only such device in the U.S.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'INSP';
UPDATE public.stocks SET mission_story = 'Makes Zio, a wearable patch that records heart rhythms for up to two weeks to help detect conditions like atrial fibrillation.', proof = 'Its Zio patch is worn for up to 14 days, and the recordings are analyzed with AI-assisted software.', proof_source_url = 'https://s205.q4cdn.com/296879096/files/doc_news/iRhythm-Holdings-Announces-Fourth-Quarter-and-Full-Year-2025-Financial-Results-2026.pdf',
  things_to_know = ARRAY['Lost about $45 million in 2025, and its revenue depends on what insurers pay for heart monitoring.', 'In June 2026, hackers stole patient data from business apps it uses and demanded a ransom; it says its devices and patient care were not affected.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'IRTC';
UPDATE public.stocks SET mission_story = 'Develops tiny implants and drug-delivery treatments for glaucoma and other chronic eye diseases.', proof = 'Its iStent was described as the smallest medical device ever approved by the FDA.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001192448/000104746915004677/a2224644zs-1.htm',
  things_to_know = ARRAY['Lost money in 2025, partly due to a one-time $113 million write-down, even as sales grew 32%.']::text[], in_feed = true,
  caution_headline = 'Up about 139% in the year to Oct 26, 2026', caution_reason = 'Its sales jumped about 50% in the second quarter of 2026 as its iDose TR glaucoma implant and Epioxa eye treatment took off.', caution_source_url = 'https://www.biospace.com/press-releases/glaukos-announces-second-quarter-2026-financial-results', caution_checked_on = '2026-10-27'
