UPDATE public.stocks SET mission_story = 'One of the largest makers of networking equipment, with a growing security business that includes Splunk.', proof = 'It bought Splunk in March 2024 for about $28 billion, its largest acquisition ever.', proof_source_url = 'https://www.securityweek.com/cisco-completes-28-billion-acquisition-of-splunk/',
  things_to_know = ARRAY['Security makes up only about a fifth of Cisco''s revenue.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'CSCO';
UPDATE public.stocks SET mission_story = 'Makes safety gear that protects firefighters and workers, from breathing equipment to gas detectors and hard hats.', proof = 'It was founded in 1914 to make safety equipment for coal miners.', proof_source_url = 'https://webapps.msasafety.com/landingpages/msa100/timeline/timeline.html',
  things_to_know = ARRAY['Its sales depend on spending by fire departments and by energy, utility, construction and manufacturing companies.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'MSA';
UPDATE public.stocks SET mission_story = 'Provides home security systems and 24/7 alarm monitoring for homes and businesses.', proof = 'It traces its roots to 1874, when it began offering alarm services by telegraph.', proof_source_url = 'https://newsroom.adt.com/adt-our-story',
  things_to_know = ARRAY['Carries about $7.8 billion of debt.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ADT';
UPDATE public.stocks SET mission_story = 'Makes locks and access systems, including Schlage, that secure homes, schools and businesses.', proof = 'It owns Schlage, a lock brand founded in 1920 that received the first patents for cylindrical and push-button locks.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1579241/000157924120000013/alle10k12312019doc.htm',
  things_to_know = ARRAY['Its sales are tied to construction and renovation activity.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ALLE';
UPDATE public.stocks SET mission_story = 'Makes body cameras, evidence software and TASER devices for police, with a stated goal of making the bullet obsolete.', proof = 'In 2022 it set a goal of cutting gun-related deaths between U.S. police and the public in half by 2033.', proof_source_url = 'https://www.bailliegifford.com/en/usa/non-professional-investor/insights/ic-article/2026-q1-finra-axon-rewiring-public-safety-10060486/',
  things_to_know = ARRAY['TASER devices are weapons, and civil-rights groups have raised concerns about its cameras and surveillance tools.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'AXON';
UPDATE public.stocks SET mission_story = 'Makes airbags and seatbelts for carmakers around the world, with a stated goal of saving more lives on the road.', proof = 'Autoliv estimates its products saved about 40,000 lives and prevented around 600,000 injuries in 2025.', proof_source_url = 'https://tools.prnewswire.com/en-us/live/20823/release/20260219EN91486',
  things_to_know = ARRAY['Its sales depend on how many cars are built worldwide, and it expects little sales growth in 2026.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ALV';
UPDATE public.stocks SET mission_story = 'Makes the chips and software behind driver-assistance features, like automatic emergency braking, that help cars avoid crashes.', proof = 'It had shipped 100 million of its EyeQ driver-assistance chips by the end of 2021.', proof_source_url = 'https://intel.com/content/www/us/en/newsroom/news/mobileye-celebrates-100-million-eyeq-chips-shipped.html',
  things_to_know = ARRAY['Lost about $392 million in 2025 under standard accounting, even as revenue grew 15%.']::text[], in_feed = true,
  caution_headline = 'Down about 50% in the year to Oct 26, 2026', caution_reason = 'It fell about 15% in one day in July 2026 when founder Amnon Shashua said he would step down as CEO.', caution_source_url = 'https://www.jpost.com/business-and-innovation/tech-and-start-ups/article-903726', caution_checked_on = '2026-10-27'
  WHERE ticker = 'MBLY';
UPDATE public.stocks SET mission_story = 'Runs psychiatric hospitals, addiction recovery centers and outpatient opioid treatment clinics across the United States.', proof = 'At the end of 2025 it operated 277 behavioral health facilities with over 12,500 beds in 40 states and Puerto Rico.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1520697/000119312526078266/achc-20251231.htm',
  things_to_know = ARRAY['Federal prosecutors and the SEC are investigating its hospital admissions, length-of-stay and billing practices; the outcome is not yet known.', 'It wrote down about $1 billion in asset values in 2025 and paid $179 million to settle an older shareholder lawsuit.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ACHC';
UPDATE public.stocks SET mission_story = 'Runs one of the largest networks of psychiatric and addiction treatment facilities in the U.S. and U.K., and in 2026 bought online therapy service Talkspace.', proof = 'As of early 2026 it operated 346 inpatient and 119 outpatient behavioral health facilities across the U.S., the U.K. and Puerto Rico.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/352915/000119312526071676/uhs-20251231.htm',
  things_to_know = ARRAY['Behavioral health is only part of the business: about 43% of 2025 revenue (counting a small insurance unit), with most of the rest from general hospitals.', 'A Virginia jury found its Cumberland children''s psychiatric hospital liable in 2024 over sexual abuse by a former medical director; it is appealing and about 40 similar claims are pending.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'UHS';
UPDATE public.stocks SET mission_story = 'Provides outpatient therapy and psychiatric care for children, teens and adults, both in person and by video, mostly covered by insurance.', proof = 'By mid-2026 it had about 8,540 psychiatrists, psychologists, nurse practitioners and therapists in 33 states, and handled 2.6 million visits in one quarter.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001845257/000119312526336057/lfst-ex99_1.htm',
  things_to_know = ARRAY['It only turned a profit in 2025, earning $9.7 million after losing $57 million in 2024; its stock more than doubled over the past year as results improved.']::text[], in_feed = true,
  caution_headline = 'Up about 151% in the year to Oct 26, 2026', caution_reason = 'Its results improved sharply: it turned its first profit in 2025, earning $9.7 million after losing $57 million in 2024.', caution_source_url = 'https://www.sec.gov/Archives/edgar/data/1845257/000119312526067858/lfst-ex99_1.htm', caution_checked_on = '2026-10-27'
  WHERE ticker = 'LFST';
UPDATE public.stocks SET mission_story = 'Owns BetterHelp, a large online therapy service, alongside virtual doctor visits and chronic-condition programs for employers and health plans.', proof = 'BetterHelp offers online counseling and therapy through a network of nearly 35,000 licensed clinicians, per Teladoc''s 2025 annual report.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1477449/000147744926000012/tdoc-20251231.htm',
  things_to_know = ARRAY['It is losing money (a $38.9 million loss in the second quarter of 2026), and BetterHelp revenue fell 12% as users shift from paying cash to using insurance.', 'In 2023 BetterHelp paid $7.8 million to settle FTC charges that it shared users'' health questionnaire data with advertisers such as Facebook.']::text[], in_feed = true,
  caution_headline = 'Typically swings about 2.1 times as much as the overall market', caution_reason = 'It is losing money, and revenue from its BetterHelp therapy service fell 12% in the second quarter of 2026.', caution_source_url = 'https://www.sec.gov/Archives/edgar/data/0001477449/000147744926000036/tdoc-20260630xexx991.htm', caution_checked_on = '2026-10-27'
  WHERE ticker = 'TDOC';
UPDATE public.stocks SET mission_story = 'Makes medicines for schizophrenia, bipolar disorder, alcohol and opioid dependence, and the sleep disorder narcolepsy.', proof = 'In the second quarter of 2026 its medicines Vivitrol, Aristada, Lybalvi and Lumryz together had about $412 million in sales.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001520262/000119312526318844/alks-ex99_1.htm',
  things_to_know = ARRAY['It borrowed $1.525 billion in early 2026 to help pay for buying the narcolepsy drugmaker Avadel.', 'Much of its hoped-for growth rides on alixorexton, an experimental narcolepsy pill that is still in late-stage trials.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ALKS';
UPDATE public.stocks SET mission_story = 'Makes Auvelity, a depression pill, and Sunosi, which treats extreme daytime sleepiness from sleep apnea or narcolepsy.', proof = 'Auvelity sales grew 51% from a year earlier to $180.3 million in the second quarter of 2026.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001579428/000119312526341206/axsm-ex99_1.htm',
  things_to_know = ARRAY['It is still losing money: its net loss was $51.3 million in the second quarter of 2026.', 'Most of its sales come from one medicine, Auvelity ($180.3 million of $218.4 million in the second quarter of 2026).']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'AXSM';
UPDATE public.stocks SET mission_story = 'Makes Nuplazid, a medicine for the hallucinations and delusions of Parkinson''s disease psychosis, and Daybue for the rare disorder Rett syndrome.', proof = 'Nuplazid had $183 million in sales in the second quarter of 2026, up 9% from a year earlier.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001070494/000119312526332858/acad-ex99_1.htm',
  things_to_know = ARRAY['Its next hoped-for medicine, remlifanserin for Alzheimer''s psychosis, narrowly missed its main goal in a mid-stage trial in September 2026; it is still being tested in larger trials.', 'All of its sales come from two medicines, Nuplazid and Daybue.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'ACAD';
UPDATE public.stocks SET mission_story = 'Makes Wakix, a medicine for daytime sleepiness and sudden muscle weakness in people with the sleep disorder narcolepsy.', proof = 'Wakix sales were $261.3 million in the second quarter of 2026, up 30% from a year earlier, with about 8,950 patients on it.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001802665/000110465926090086/hrmy-20260804xex99d1.htm',
  things_to_know = ARRAY['Almost all of its sales come from one medicine, Wakix.', 'A patent case against a would-be generic maker of Wakix (AET) was still waiting for a court decision in late October 2026.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'HRMY';
UPDATE public.stocks SET mission_story = 'Makes Ingrezza for uncontrollable movements caused by some mental health medicines, and is testing new depression and schizophrenia drugs.', proof = 'Ingrezza had $716 million in sales in the second quarter of 2026, up 15% from a year earlier.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0000914475/000091447526000035/q2-2026xearningsrelease.htm',
  things_to_know = ARRAY['Ingrezza brings in most of its money ($716 million of $959 million in the second quarter of 2026).', 'Starting in 2027, Medicare drug plans must cover rival Austedo at a government-negotiated price, which could pressure Ingrezza.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'NBIX';
UPDATE public.stocks SET mission_story = 'Makes medicines for the sleep disorders narcolepsy and idiopathic hypersomnia, plus treatments for epilepsy and several cancers.', proof = 'Its sleep medicine Xywav had $471.2 million in sales in the second quarter of 2026, with about 11,275 narcolepsy patients on it.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001232524/000123252426000044/a2q26financialpr.htm',
  things_to_know = ARRAY['It owed about $4.4 billion in long-term debt at the end of June 2026.', 'Generic drugmakers Lupin and Teva want to sell copies of Xywav, its top medicine; Jazz is fighting them in patent lawsuits.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'JAZZ';
UPDATE public.stocks SET mission_story = 'Formerly MindMed, it is developing DT120, a carefully dosed LSD-based tablet, to treat anxiety and depression.', proof = 'DT120 met its main goal in its second late-stage anxiety trial in September 2026, cutting anxiety scores 9.8 points versus 4.7 on placebo.', proof_source_url = 'https://www.psychiatrictimes.com/view/positive-topline-results-from-phase-3-panorama-study-of-dt120-odt-in-generalized-anxiety-disorder',
  things_to_know = ARRAY['It has no approved medicine yet and lost $159.0 million in the second quarter of 2026.', 'Its stock nearly tripled over the past year on trial successes, so it can swing sharply on news such as the FDA''s decision.']::text[], in_feed = true,
  caution_headline = 'Up about 188% in the year to Oct 26, 2026, and swings about 2.2 times as much as the overall market', caution_reason = 'Its LSD-based anxiety treatment succeeded in late-stage trials in 2026, but it has no approved product yet, so FDA news can move the stock sharply.', caution_source_url = 'https://www.psychiatrictimes.com/view/positive-topline-results-from-phase-3-panorama-study-of-dt120-odt-in-generalized-anxiety-disorder', caution_checked_on = '2026-10-27'
  WHERE ticker = 'DFTX';
UPDATE public.stocks SET mission_story = 'Is developing COMP360, a psilocybin treatment given with therapist support, for depression that other treatments haven''t helped.', proof = 'COMP360 succeeded in two late-stage trials in treatment-resistant depression, and Compass expects to finish its FDA application in late 2026.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001816590/000181659026000059/q22026pressrelease.htm',
  things_to_know = ARRAY['COMP360 is not approved yet; a launch, expected in the first half of 2027, also needs the DEA to reclassify psilocybin.', 'It lost $253.8 million in the second quarter of 2026, mostly from non-cash charges, and has no product sales.']::text[], in_feed = true,
  caution_headline = 'Typically swings about 2.6 times as much as the overall market', caution_reason = 'Its value rests on one treatment that isn''t approved yet, a psilocybin therapy for hard-to-treat depression, so trial and FDA news can move the stock sharply.', caution_source_url = 'https://www.sec.gov/Archives/edgar/data/0001816590/000181659026000059/q22026pressrelease.htm', caution_checked_on = '2026-10-27'
  WHERE ticker = 'CMPS';
UPDATE public.stocks SET mission_story = 'Makes farm machinery with built-in precision technology, such as sprayers that use cameras to spot weeds and spray only where needed.', proof = 'Farmers used its See & Spray system on more than 5 million acres in 2025, cutting non-residual herbicide use by nearly 50% on average.', proof_source_url = 'https://www.farms.com/news/john-deere-see-and-spray-saves-millions-234493.aspx',
  things_to_know = ARRAY['Its sales follow the farm economy: Deere expects U.S. and Canada sales of large farm machines to fall 15% to 20% in fiscal 2026.', 'In July 2026 it settled a U.S. government lawsuit claiming it kept farmers from repairing their own machines; it must share repair tools for 10 years.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'DE';
UPDATE public.stocks SET mission_story = 'Makes Fendt, Massey Ferguson and Valtra farm machines and sells PTx precision kits that help farmers plant, fertilize and spray more precisely.', proof = 'Its PTx precision farming brand launched 14 new products in 2025, and AGCO aims to reach $2 billion in precision farming sales by 2029.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/880266/000088026626000027/agco2025annualreport_ars.htm',
  things_to_know = ARRAY['Weak farm demand cut its 2025 sales 13.5% to about $10.1 billion, with North America down about 28%.', 'It took a $351 million write-down in 2024 on the North American part of its PTx Trimble precision farming business.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'AGCO';
UPDATE public.stocks SET mission_story = 'Makes Case IH and New Holland farm machines and Raven precision technology, including camera systems that spray only where weeds grow.', proof = 'Its Case IH SenseApply camera-guided spot sprayer was one of three CNH technologies named to the ASABE AE50 2026 list of top farm engineering innovations.', proof_source_url = 'https://s205.q4cdn.com/962820841/files/doc_news/AE50-2026-ASABE-lists-three-Ag-Tech-innovations-from-CNH-2026.pdf',
  things_to_know = ARRAY['Weak farm demand cut its 2025 agriculture sales 11.5% to about $12.4 billion, with North America down 26%.', 'In 2025 it wrote off $172 million of technology value from its Raven and Bennamann acquisitions.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'CNH';
UPDATE public.stocks SET mission_story = 'Makes Zimmatic center pivot irrigation systems and FieldNET remote controls that help farmers grow crops while conserving water, energy and labor.', proof = 'Its irrigation segment had $541.5 million of sales in fiscal 2026, about 85% of the company''s total revenue.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/836157/000119312526428926/lnn-20260831.htm',
  things_to_know = ARRAY['It leans on a few big projects: one Middle East and North Africa irrigation customer made up 12% of fiscal 2026 revenue.', 'It is defending product liability lawsuits over its X-Lite highway guardrail end terminal.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'LNN';
UPDATE public.stocks SET mission_story = 'Makes Valley center pivot irrigation and remote farm-monitoring tools that save water, plus steel poles and structures for the power grid.', proof = 'Its irrigation technology had more than 175,000 connected devices helping farmers spot field problems and use water and energy more efficiently, per its 2025 annual report.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/102729/000010272926000007/vmi-20251227x10k.htm',
  things_to_know = ARRAY['Its agriculture sales fell 5.8% in 2025 to about $1.02 billion and that segment''s operating income dropped 33%, as farm demand weakened.', 'It recorded about $91 million of asset write-downs in 2025, mostly in its solar and access systems businesses.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'VMI';
UPDATE public.stocks SET mission_story = 'Sells crop protection products to farmers, mostly chemical weed and insect killers, plus a growing line of biologicals and other nature-based products.', proof = 'Its biologicals product line had $519 million of sales in 2025, up from $476 million in 2024, and in June 2026 it took full ownership of New Zealand biologicals maker Biotelliga.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1755672/000175567226000028/newcorteva-fy23xfy25carvex.htm',
  things_to_know = ARRAY['Its stock fell about 84% on October 1, 2026 because it spun off its seed business as Vylor; owners got one Vylor share per Corteva share.', 'Fifteen states and Guam sued, claiming the split was meant to shield assets from PFAS pollution claims tied to former DuPont businesses; Corteva calls the claims unproven.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'CTVA';
UPDATE public.stocks SET mission_story = 'Produces potash, nitrogen and phosphate fertilizers and runs farm-supply stores whose crop consultants help farmers test soil and apply fertilizer more precisely.', proof = 'Its retail business has over 4,200 crop consultants who help farmers with soil sampling, variable-rate fertilizer application and crop monitoring across more than 1,800 locations.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1725964/000119312526081326/d56746dex991.htm',
  things_to_know = ARRAY['Making nitrogen fertilizer burns and uses natural gas; its production plants caused about 95% of its direct and energy-related greenhouse gas emissions in 2025.', 'Its profits swing with fertilizer and crop prices, and it is reviewing options for its phosphate business.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'NTR';
UPDATE public.stocks SET mission_story = 'Runs grocery stores built around fresh produce, with many organic, plant-based and gluten-free foods.', proof = 'It operated 490 stores in 25 states at the end of June 2026.', proof_source_url = 'https://investors.sprouts.com/news/news-details/2026/Sprouts-Farmers-Market-Inc--Reports-Second-Quarter-2026-Results/default.aspx',
  things_to_know = ARRAY['Sales at stores open at least a year fell 1.0% in the second quarter of 2026 as shoppers watched prices.', 'Its stock is down about 38% from a year ago after its fast growth slowed sharply.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'SFM';
UPDATE public.stocks SET mission_story = 'Runs fast-casual Mediterranean restaurants serving bowls and pitas made with healthful ingredients.', proof = 'It had 476 restaurants after opening 17 more in the quarter ended July 12, 2026, when sales at existing restaurants rose 9.0%.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001639438/000162828026055709/earningsrelease2026q2.htm',
  things_to_know = ARRAY['Its stock moves much more than the overall market and is about 19% lower than a year ago.', 'Its restaurant profit margin slipped to 25.7% from 26.3% a year earlier as ingredient, delivery and wage costs rose.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'CAVA';
UPDATE public.stocks SET mission_story = 'Runs salad and bowl restaurants with a mission to build healthier communities by connecting people to real food.', proof = 'It runs over 285 restaurants across the United States.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001477815/000162828026054324/q226sweetgreenearningsrele.htm',
  things_to_know = ARRAY['Sales at existing restaurants fell 6.2% in the second quarter of 2026, and it lost $26.3 million that quarter.', 'Its profit for the first half of 2026 came from a one-time gain on selling its kitchen-robot business, Spyce.']::text[], in_feed = true,
  caution_headline = 'Typically swings about 2.2 times as much as the overall market', caution_reason = 'Sales at its existing restaurants fell 6.2% in the second quarter of 2026, and it lost $26.3 million that quarter.', caution_source_url = 'https://www.sec.gov/Archives/edgar/data/0001477815/000162828026054324/q226sweetgreenearningsrele.htm', caution_checked_on = '2026-10-27'
  WHERE ticker = 'SG';
UPDATE public.stocks SET mission_story = 'Makes tests that food companies use to catch harmful bacteria and other contamination before food reaches people.', proof = 'Its food safety products brought in $163.2 million in the quarter ended August 31, 2026, in over 140 countries.', proof_source_url = 'https://www.biospace.com/press-releases/neogen-reports-first-quarter-financial-results-for-fiscal-year-2027',
  things_to_know = ARRAY['It lost $11.9 million in that quarter and had $774.2 million in long-term debt.', 'It is still moving production of its Petrifilm food-safety tests into its own factory, a switch starting in November 2026.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'NEOG';
UPDATE public.stocks SET mission_story = 'Grows, ships and sells fresh fruit and vegetables, such as bananas and pineapples, around the world.', proof = 'It sells fresh produce in over 85 countries and had about $2.5 billion in revenue in the second quarter of 2026.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001857475/000185747526000074/doleplcreportssecondquarte.htm',
  things_to_know = ARRAY['Its profits are thin and swing with fruit costs: a key profit measure fell 14.8% in the second quarter of 2026 on higher fruit sourcing costs.', 'It had about $746 million in debt, net of cash, at the end of June 2026.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'DOLE';
UPDATE public.stocks SET mission_story = 'Develops medicines for lung, breast, blood and other cancers, its biggest business, plus treatments for rare diseases and heart, kidney and diabetes conditions.', proof = 'Its cancer medicines brought in about $14.1 billion in the first half of 2026, 46% of its total revenue.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0000901832/000110465926086846/azn-20260630x6k.htm',
  things_to_know = ARRAY['Farxiga, its top heart, kidney and diabetes drug, lost U.S. patent protection, and China''s state bulk-buying program is cutting prices.', 'In 2026 Chinese prosecutors charged its China unit with illegally collecting personal data and illegal trading; two former staff, including the ex-China head, also face insurance fraud charges.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'AZN';
UPDATE public.stocks SET mission_story = 'Makes cancer medicines such as Kisqali for breast cancer and Pluvicto for prostate cancer, alongside heart, immune and brain medicines.', proof = 'Its cancer medicines brought in about $8.5 billion in the first half of 2026, up 34% at constant exchange rates.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001114448/000111444826000012/nvs-20260630-99_2.htm',
  things_to_know = ARRAY['Sales of its heart failure drug Entresto roughly halved in early 2026 after U.S. generics arrived, so total sales barely grew.', 'It paid about $12 billion in cash for Avidity Biosciences in 2026, funded partly with an $11 billion bridge loan.']::text[], in_feed = true,
