  WHERE ticker = 'NVS';
UPDATE public.stocks SET mission_story = 'Makes cancer medicines such as Carvykti and Tecvayli for multiple myeloma and Rybrevant for lung cancer, plus psychiatric medicines and medical devices.', proof = 'Its cancer medicines brought in about $22 billion in the first nine months of 2026, up 18.7% from a year earlier.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/200406/000020040626000189/a2026q3exhibit992.htm',
  things_to_know = ARRAY['In July 2026 it proposed paying $5.5 billion to settle about 76,000 lawsuits claiming its talc products caused ovarian cancer; it denies the claims, and the deal needs 95% of claimants to join.', 'Falling sales of its immune drug Stelara cut its medicines growth by about 7 percentage points in the third quarter of 2026, and it plans to separate its orthopaedics business.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'JNJ';
UPDATE public.stocks SET mission_story = 'Makes genomic tests that help doctors diagnose cancer and choose treatment, led by its Decipher prostate cancer and Afirma thyroid tests.', proof = 'Its Decipher prostate cancer test was used about 102,000 times in 2025, up 27% from 2024.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1384101/000138410126000008/vcyt-02x25x20268xkearnings.htm',
  things_to_know = ARRAY['Most of its revenue comes from just two tests, Decipher Prostate and Afirma, so a drop in either would hurt results.', 'About half of its testing revenue comes from Medicare and Medicare Advantage, so government payment decisions matter a lot.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'VCYT';
UPDATE public.stocks SET mission_story = 'Runs genetic tests on cancer patients'' tumors and uses a large library of patient data and AI to help doctors and drugmakers choose treatments.', proof = 'The FDA approved its xT CDx tumor-sequencing test as a companion diagnostic for cancer treatment in April 2023.', proof_source_url = 'https://www.accessdata.fda.gov/scripts/cdrh/cfdocs/cfpma/pma.cfm?id=P210011',
  things_to_know = ARRAY['Lost about $245 million in 2025; it reported a small profit in the second quarter of 2026, helped by gains on investments it holds.', 'In July 2026 it agreed to buy Personalis for about $1.5 billion, paid mostly in new Tempus shares; the deal still needs approvals.']::text[], in_feed = true,
  caution_headline = 'Typically swings about 3.5 times as much as the overall market', caution_reason = 'It lost about $245 million in 2025 and only recently reported a small profit, helped by gains on investments it holds.', caution_source_url = 'https://www.sec.gov/Archives/edgar/data/1717115/000119312526066931/tem-ex99_1.htm', caution_checked_on = '2026-10-27'
  WHERE ticker = 'TEM';
UPDATE public.stocks SET mission_story = 'Makes wearable devices that send electric fields through the body to slow cancer cell growth, used for brain, lung and pancreatic cancers.', proof = 'The FDA approved its Optune Pax device for adults with locally advanced pancreatic cancer in February 2026.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1645113/000164511326000010/paxfdadecisionpr.htm',
  things_to_know = ARRAY['Most of its revenue still comes from one product, Optune Gio for glioblastoma brain cancer, sold mainly in the U.S., Germany, France and Japan.', 'Lost about $136 million in 2025, has a history of losses, and carries about $196 million of secured debt.']::text[], in_feed = true,
