  WHERE ticker = 'NVCR';
UPDATE public.stocks SET mission_story = 'Develops vaccines meant to protect against more strains of the bacteria behind pneumonia and meningitis than today''s shots do.', proof = 'In October 2026 its 31-strain vaccine, VAX-31, met its main goals in a Phase 3 trial of 4,047 adults against Prevnar 20 and Capvaxive.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1649094/000119312526413168/d21202dex991.htm',
  things_to_know = ARRAY['It has no approved products or product revenue, lost about $767 million in 2025, and plans to apply for approval only in the first half of 2028.', 'In October 2026 it raised about $1.1 billion by selling new shares and convertible bonds, which spreads ownership over more shares.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'PCVX';
UPDATE public.stocks SET mission_story = 'Makes medical scanners, ultrasound machines, patient monitors and imaging drugs that help doctors find and diagnose disease.', proof = 'The FDA cleared its Photonova Spectra photon-counting CT scanner in March 2026, built to show small lesions and fine blood vessels.', proof_source_url = 'https://www.gehealthcare.com/en/about/newsroom/press-releases/ge-healthcares-photonova-spectra-photon-counting-ct-receives-fda-clearance',
  things_to_know = ARRAY['Its sales in China fell 4.6% in 2025, to about $2.25 billion, as demand there weakened.', 'It carried about $10 billion of debt at the end of 2025.']::text[], in_feed = true,
