  things_to_know = ARRAY['It was defending about 7,090 lawsuits over its hernia repair devices and about 3,850 over implantable ports as of June 2026.', 'In April 2026 the FDA sent a warning letter to its El Paso plant, which makes ChloraPrep skin antiseptic, citing manufacturing quality problems.']::text[], in_feed = true,
