UPDATE public.stocks SET mission_story = 'Makes spine and bone implants, surgical robots and spinal cord stimulators that help treat back, neck and joint problems and chronic pain.', proof = 'Globus launched 9 new products in 2025 and operates in 65 countries.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1237831/000162828026011209/gmed-20251231.htm',
  things_to_know = ARRAY['An FDA warning letter from July 2024 about complaint handling and safety reporting for its ExcelsiusGPS surgical robot was still open as of February 2026.', 'Sales of its robots and imaging systems fell about 8% in 2025, to about $141 million, as fewer units were placed in U.S. hospitals.']::text[], in_feed = true,
