  things_to_know = ARRAY['Its shares rose about 64% in the past year as profits grew; in Q2 2026 its net income rose 41% and it raised its full-year outlook.', 'It carries about $1.3 billion of net debt, and its premium memberships could suffer if people cut back on spending.']::text[], in_feed = true,
