UPDATE public.stocks SET mission_story = 'Develops experimental medicines for obesity and metabolic disease, led by VK2735, which is in late-stage trials as both a weekly shot and a pill.', proof = 'In its Phase 2 VENTURE study, weekly VK2735 shots cut body weight by up to 14.7% in 13 weeks.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1607678/000119312526046876/vktx-20251231.htm',
  things_to_know = ARRAY['It has no approved products or sales yet and lost $286 million in the first half of 2026; its big Phase 3 results are still ahead.', 'In September 2026 it priced a $500 million sale of new shares and convertible notes, adding stock and debt to fund its trials.']::text[], in_feed = true,
