UPDATE public.stocks SET mission_story = 'Sells connected exercise bikes, treadmills and rowers plus app subscriptions with live and on-demand classes, so people can work out at home.', proof = 'It had about 5.5 million members, including 2.55 million paid connected fitness subscriptions, as of June 30, 2026.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1639825/000163982526000038/pton-20260630.htm',
  things_to_know = ARRAY['Its paid equipment subscriptions fell 8.8% in the year to June 2026, it expects sales to shrink again in fiscal 2027, and its shares fell about 32% in a year.', 'It carries about $1.3 billion of debt, though that is largely offset by about $1.2 billion of cash.']::text[], in_feed = true,
