  things_to_know = ARRAY['Only part of the business is health-related: about 37% of Q2 2026 sales came from Fitness, with the rest from outdoor, marine, aviation and car electronics.', 'It warns that tariffs and global trade changes could affect results; its Q2 2026 profit margin got a lift from about $21 million in tariff refunds.']::text[], in_feed = true,
