  things_to_know = ARRAY['About a fifth of its 2025 revenue ($5.48 billion of $28.48 billion) came from its underground segment, which includes work on natural gas and oil pipelines.', 'It co-owns LUMA Energy, which runs Puerto Rico''s power grid; in December 2025 Puerto Rico''s government sued to cancel LUMA''s contract over blackouts and slow rebuilding.']::text[], in_feed = true,
