  things_to_know = ARRAY['Almost half of its 2025 revenue (45.3%) came from electrical work on commercial and industrial buildings, not the power grid.', 'Most of that building work (84.5% in 2025) is done at a fixed price, so cost overruns come out of its profits.']::text[], in_feed = true,
