  things_to_know = ARRAY['Its top ten customers make up about 42% of its sales, so a slowdown in utility spending would hurt.', 'Not all of its products are for the electric grid: some go to gas utilities, and some of its electrical products are sold mainly to oil and gas and mining customers.']::text[], in_feed = true,
