UPDATE public.stocks SET mission_story = 'The largest regulated U.S. water and wastewater utility, supplying safe drinking water to about 14 million people in 14 states.', proof = 'It spent $1.519 billion on pipes, plants and other infrastructure in the first half of 2026.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001410636/000141063626000120/awk-20260630.htm',
  things_to_know = ARRAY['It agreed to merge with Essential Utilities, which also runs natural gas utilities; the deal is expected to close by early 2027 if regulators approve.', 'Its long-term debt rose to about $14.0 billion by June 2026, and its prices are set by state regulators.']::text[], in_feed = true,
