  WHERE ticker = 'AWK';
UPDATE public.stocks SET mission_story = 'Supplies water to more than 80 California communities and runs water and wastewater systems on 12 U.S. military bases.', proof = 'Its Golden State Water utility serves about 265,200 customer connections in more than 80 California communities.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001056903/000162828026053403/exhibit991pressrelease2026.htm',
  things_to_know = ARRAY['Its profits depend on California regulators approving rate increases; second-quarter 2026 earnings rose mainly because of new rates.', 'It also owns a small electric utility in Big Bear Lake, California, and its military-base work depends on U.S. government contracts.']::text[], in_feed = true,
  caution_headline = NULL, caution_reason = NULL, caution_source_url = NULL, caution_checked_on = NULL
  WHERE ticker = 'AWR';
UPDATE public.stocks SET mission_story = 'Provides drinking water to more than 2.2 million people in California, Hawaii, New Mexico, Washington and Texas.', proof = 'It invested a record $276.4 million in water infrastructure in the first half of 2026.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001035201/000110465926088379/tm2621659d1_ex99-1.htm',
  things_to_know = ARRAY['Its profits depend on regulators'' rate decisions; second-quarter 2026 results were lifted by a delayed California rate increase applied back to January.', 'New federal limits on PFAS "forever chemicals" in drinking water may require costly treatment upgrades.']::text[], in_feed = true,
