UPDATE public.stocks SET mission_story = 'Formerly SJW Group, it runs water and wastewater utilities serving over 1.6 million people in California, Connecticut, Maine and Texas.', proof = 'It invested $206.9 million in water infrastructure in the first half of 2026.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0000766829/000162828026049836/exhibit991-2q2026.htm',
  things_to_know = ARRAY['Its profits depend on state regulators approving rate increases to pay back what it spends on pipes and plants.', 'It is buying Texas water utility Quadvest for about $540 million, a deal still going through regulators in mid-2026.']::text[], in_feed = true,
