UPDATE public.stocks SET mission_story = 'Makes pumps, treatment systems, smart meters and services that move, clean and track water for cities and industries.', proof = 'It took in $3.1 billion of new orders in the second quarter of 2026, up 42% from a year earlier.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/0001524472/000152447226000108/xyl07282026ex991.htm',
