UPDATE public.stocks SET mission_story = 'Owns Hach water-testing instruments, Trojan UV disinfection and ChemTreat water treatment, helping utilities and factories keep water clean.', proof = 'Its Water Quality business had $3.3 billion in sales in 2025.', proof_source_url = 'https://www.sec.gov/Archives/edgar/data/1967680/000196768026000018/a2025_annualxreportxfina.htm',
